import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = "/data"

@app.route("/search", methods=["POST"])
def search():
    data = request.get_json()
    if data is None:
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get("search_content")
    search_filename = data.get("search_filename")
    search_dir = data.get("search_dir")

    # Validate that at least one search parameter is provided
    if search_content is None and search_filename is None:
        return jsonify({"error": "Invalid input: at least one of search_content or search_filename must be provided"}), 400

    # Determine the directory to search in
    if search_dir:
        # Resolve the search directory relative to DATA_DIR or as absolute path
        # Join with DATA_DIR if not absolute
        if os.path.isabs(search_dir):
            search_path = search_dir
        else:
            search_path = os.path.join(DATA_DIR, search_dir)
    else:
        search_path = DATA_DIR

    # Validate that the search path exists and is within DATA_DIR
    # Normalize paths to prevent directory traversal
    data_dir_norm = os.path.normpath(DATA_DIR)
    search_path_norm = os.path.normpath(search_path)

    # Check if search_path is within DATA_DIR
    if not search_path_norm.startswith(data_dir_norm + os.sep) and search_path_norm != data_dir_norm:
        return jsonify({"error": "Invalid search directory"}), 400

    if not os.path.isdir(search_path):
        return jsonify({"error": "Search directory does not exist"}), 400

    found_files = []

    # Walk through the directory
    for root, dirs, files in os.walk(search_path):
        for filename in files:
            filepath = os.path.join(root, filename)

            # Check filename match if search_filename is provided
            if search_filename is not None:
                # Check if the file starts with the search filename
                if not filename.startswith(search_filename):
                    continue

            # Check content match if search_content is provided
            if search_content is not None:
                try:
                    with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read()
                        if search_content not in content:
                            continue
                except (IOError, OSError):
                    # Skip files that cannot be read
                    continue

            found_files.append(filepath)

    return jsonify({"files": found_files}), 200

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
